use vstd::prelude::*;

verus! {
    // The 13 supported time units
    #[derive(PartialEq, Eq)]
    enum TimeUnit {
        Year,
        Month,
        Week,
        Day,
        Hour,
        Minute,
        Second,
        Millisecond,
        Microsecond,
        Nanosecond,
        Picosecond,
        Femtosecond,
        Attosecond,
    }

    // A signed‐64‐bit time duration tagged with one of the above units
    struct TimeDelta64 {
        value: i64,
        unit:  TimeUnit,
    }

    // Construct a TimeDelta64 from a given i64 and TimeUnit.
    // Since `value` is already an i64, it is by definition within
    // [i64::MIN..=i64::MAX], so no extra precondition is needed.
    fn timedelta64(value: i64, unit: TimeUnit) -> (result: TimeDelta64)
        ensures
            // The returned record directly reflects the inputs
            result.value == value,
            result.unit  == unit,
    {
        TimeDelta64 { value, unit }
    }
}

fn main() {
    // Simple smoke‐test in ordinary Rust
    let dt = timedelta64(42, TimeUnit::Minute);
    assert!(dt.value == 42 && dt.unit == TimeUnit::Minute);
}